typedef struct{const char*id;EVP_PKEY*key;} Key;
typedef struct{Key k[8];size_t n;} Keys;
static int lookup(void*ctx,const char*id,EVP_PKEY**out){Keys*k=ctx;for(size_t i=0;i<k->n;i++)if(!strcmp(k->k[i].id,id)){if(EVP_PKEY_up_ref(k->k[i].key)!=1)return-1;*out=k->k[i].key;return 0;}return-1;}
static int authorize(void*ctx,const char*id){(void)ctx;return strcmp(id,"gov:model");}
static EVP_PKEY*keygen(void){return EVP_PKEY_Q_keygen(NULL,NULL,"ED25519");}
static void root(char out[65],char c){for(int i=0;i<64;i++)out[i]=c;out[64]=0;}
static void make_manifest(QrxAuraModelManifest*m){
    memset(m,0,sizeof(*m));m->version=1;snprintf(m->model_id,sizeof(m->model_id),"qrx:model:qwen-family:next-small:instruct");snprintf(m->model_version,sizeof(m->model_version),"2026.09");snprintf(m->family,sizeof(m->family),"qwen-family");snprintf(m->architecture,sizeof(m->architecture),"moe-transformer");snprintf(m->format,sizeof(m->format),"gguf");snprintf(m->quantization,sizeof(m->quantization),"q4_k_m");snprintf(m->license_id,sizeof(m->license_id),"upstream-license");snprintf(m->origin_uri,sizeof(m->origin_uri),"https://origin.invalid/model");m->max_context_tokens=131072;m->asset_count=6;
    for(uint32_t i=0;i<m->asset_count;i++){QrxAuraModelAsset*a=&m->assets[i];a->index=i;a->bytes=(uint64_t)(i+1)*1024*1024;char c=(char)('a'+i);root(a->content_root,c);}
    m->assets[0].kind=QRX_AURA_ASSET_CONFIG;m->assets[0].required_for_boot=1;
    m->assets[1].kind=QRX_AURA_ASSET_TOKENIZER;m->assets[1].required_for_boot=1;
    m->assets[2].kind=QRX_AURA_ASSET_SHARED_WEIGHTS;m->assets[2].required_for_boot=1;
    m->assets[3].kind=QRX_AURA_ASSET_EXPERT_PACK;m->assets[3].expert_first=0;m->assets[3].expert_count=8;
    m->assets[4].kind=QRX_AURA_ASSET_EXPERT_PACK;m->assets[4].expert_first=8;m->assets[4].expert_count=8;
    m->assets[5].kind=QRX_AURA_ASSET_EXPERT_PACK;m->assets[5].expert_first=16;m->assets[5].expert_count=8;
    for(uint32_t i=0;i<m->asset_count;i++)m->total_bytes+=m->assets[i].bytes;
}
static void make_profile(QrxAuraModelCapabilityProfile*p,const QrxAuraModelManifest*m){memset(p,0,sizeof(*p));p->version=1;snprintf(p->model_id,sizeof(p->model_id),"%s",m->model_id);snprintf(p->model_version,sizeof(p->model_version),"%s",m->model_version);snprintf(p->family,sizeof(p->family),"%s",m->family);snprintf(p->runtime_id,sizeof(p->runtime_id),"llama.cpp");snprintf(p->quantization,sizeof(p->quantization),"%s",m->quantization);p->tier=QRX_AURA_TIER_CLUSTER;p->min_memory_bytes=4ull<<30;p->recommended_memory_bytes=8ull<<30;p->min_storage_bytes=m->total_bytes;p->min_aggregate_milli_tokens_per_second=1000;p->min_pods=1;p->min_network_mbps=10;p->max_latency_ms=500;p->min_reliability_bps=7000;p->min_cache_hit_bps=0;p->min_expert_locality_bps=0;p->max_context_tokens=m->max_context_tokens;p->quality_bps=9000;p->coding_bps=9000;p->reasoning_bps=9000;p->rag_bps=8500;p->tool_use_bps=8500;p->is_moe=1;p->supports_single_device=1;}
