    CHECK(qrx_aura_model_provider_index_prune(idx,201)==3);qrx_aura_model_provider_index_free(idx);qrx_aura_model_catalog_free(catalog);free(idx);free(catalog);EVP_PKEY_free(gov);EVP_PKEY_free(p1);EVP_PKEY_free(p2);EVP_PKEY_free(p3);printf("phase167 AURA zero-config model fabric: PASS\n");return 0;
